--
-- Table structure for table `roster_pkmn`
--

CREATE TABLE `roster_pkmn` (
  `id` int(10) UNSIGNED NOT NULL,
  `season_id` int(11) NOT NULL,
  `active_user_id` int(11) NOT NULL,
  `showdown_pokemon_id` int(11) NOT NULL,
  `status` enum('active','dropped') NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `dropped_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

